"""A portable report and the same interactive view inside the local laboratory."""
from __future__ import annotations
import json


def markdown_report(data):
    rows = ['# 穿石 Stoneflow：因子评价研究', '',
            f"信号区间：**{data['start']} 至 {data['end']}**。课程证券列：{data['securities']:,}。", '',
            '因子预测能力与策略净交易分别评价；所有新结论为回顾性描述，不自动挑选冠军或翻转因子方向。', '',
            '## 预测能力与分组', '',
            '| 因子 / 股票池 | 未来交易日 | Rank IC均值 | ICIR（未年化） | 正IC日占比 | Q5−Q1平均报价收益 | 标签覆盖 |',
            '| --- | --- | --- | --- | --- | --- | --- |']
    def num(v): return '—' if v is None else f'{v:.4f}'
    def pct(v, digits=2): return '—' if v is None else f'{v*100:.{digits}f}%'
    for a in data['analyses']:
        for s in a['summary']:
            ic = s['rank_ic']
            rows.append(f"| {a['title']} / {a['pool']} | {s['horizon']} | {num(ic['mean'])} | {num(ic['icir'])} | {pct(ic['positive_fraction'])} | {pct(s['mean_spread'],4)} | {pct(s['label_coverage'])} |")
    rows += ['', '## 5DR跨年检查', '', '| 股票池 | 信号年份 | 未来交易日 | Rank IC均值 | 有效日 |', '| --- | --- | --- | --- | --- |']
    for a in data['analyses']:
        if a['factor_key'] == 'reversal5':
            for p in a['periods']:
                if len(p['period']) == 4:
                    rows.append(f"| {a['pool']} | {p['period']} | {p['horizon']} | {num(p['mean'])} | {p['observations']} |")
    rows += ['', '## 策略账户与评分', '',
             '以下是原始股份账户，与未扣费的因子分组报价曲线口径不同。训练期评分不与评价期收益混用。', '',
             '| 策略 | 记录 | 实际区间 | 累计收益 | 年化收益（252日） | 最大回撤 | 自定义评分 |',
             '| --- | --- | --- | --- | --- | --- | --- |']
    for a in data['accounts']:
        m = a['metrics']
        rows.append(f"| {a['key']} | {a['period']} | {m['start']} — {m['end']} | {pct(m['total_return'])} | {pct(m['annualized_return'])} | {pct(m['max_drawdown'])} | {num(a['score']['value'])} |")
    rows += ['', '## 定义、精度与限制', '']
    rows += [f"- **{key}**：{value}" for key, value in data['methods'].items()]
    rows += ['', '内置因子支持5DR、20日动量、20日突破幅度、成交额放大和20日低波动；也支持Python时点builder及date,symbol,value长表CSV。',
             '自定义CSV不能自动证明因果性；Python插件是用户明确指定的本机代码，不从网页执行任意代码。',
             '', '方法参考：[Alphalens 因子评价文档](https://quantopian.github.io/alphalens/alphalens.html)。', '']
    return '\n'.join(rows)


def render_report(data=None, live=False):
    serialized = json.dumps(data, ensure_ascii=False, allow_nan=False).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    return TEMPLATE.replace('/*__PAYLOAD__*/null', serialized).replace('/*__LIVE__*/false', 'true' if live else 'false')


